<?php
namespace App\Controllers\Api;
use App\Models\NilaiSiswaModel;
class NilaiController extends BaseApiController
{
 public function index(){ $kelas=(int)$this->request->getGet('kelas_id');$mapel=(int)$this->request->getGet('mata_pelajaran_id');$q=(new NilaiSiswaModel())->select('nilai_siswa.*,siswa.nis,siswa.nama_lengkap,komponen_nilai.nama_komponen,komponen_nilai.jenis_komponen')->join('siswa','siswa.id=nilai_siswa.siswa_id')->join('komponen_nilai','komponen_nilai.id=nilai_siswa.komponen_nilai_id')->where('komponen_nilai.kelas_id',$kelas);if($mapel)$q->where('komponen_nilai.mata_pelajaran_id',$mapel);return $this->respond(['data'=>$q->orderBy('siswa.nama_lengkap')->orderBy('komponen_nilai.urutan')->findAll()]);}
 public function save(){ $p=$this->payload();$errors=$this->validatePayload($p,['siswa_id'=>'required|is_natural_no_zero','komponen_nilai_id'=>'required|is_natural_no_zero','nilai'=>'required|decimal|greater_than_equal_to[0]|less_than_equal_to[100]','keterangan'=>'permit_empty|max_length[2000]']);if($errors)return $this->respond(['ok'=>false,'errors'=>$errors],422);$valid=db_connect()->table('siswa')->select('siswa.id')->join('komponen_nilai','komponen_nilai.kelas_id=siswa.kelas_id')->where(['siswa.id'=>(int)$p['siswa_id'],'komponen_nilai.id'=>(int)$p['komponen_nilai_id'],'komponen_nilai.aktif'=>1])->get()->getRow();if(!$valid)return $this->respond(['ok'=>false,'message'=>'Siswa dan komponen nilai tidak berada pada kelas yang sama.'],422);$model=new NilaiSiswaModel();$existing=$model->where(['siswa_id'=>(int)$p['siswa_id'],'komponen_nilai_id'=>(int)$p['komponen_nilai_id']])->first();$data=['siswa_id'=>(int)$p['siswa_id'],'komponen_nilai_id'=>(int)$p['komponen_nilai_id'],'nilai'=>(float)$p['nilai'],'keterangan'=>trim((string)($p['keterangan']??''))?:null,'dinilai_oleh'=>$this->currentUser()['id']];if($existing){$model->update($existing->id,$data);$id=$existing->id;}else{$id=$model->insert($data,true);}return $this->respond(['ok'=>true,'data'=>$model->find($id)],$existing?200:201);}
}